using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools ---
var notes = new ResearchNotes();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        nameof(WebSearchTool.SearchAsync),
        "Searches the web for the given query and returns a list of results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("Short title for the note")] string title,
         [Description("Content of the note")] string content) =>
        {
            notes.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "SaveNote",
        "Saves a research note with a title and content. Use this to record important findings."),

    AIFunctionFactory.Create(
        () => notes.GetAll(),
        "GetNotes",
        "Retrieves all saved research notes so far."),
};

// --- Build the chat client through MEAI ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Build the agent ---
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes and produce a clear,
           well-structured summary with key facts, different perspectives, and source URLs.
        Be thorough — use at least 2-3 different search queries to cover the topic well.
        """,
    tools: tools);

// --- Run ---
Console.WriteLine("Research Agent");
Console.WriteLine(new string('=', 50));

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "recent advances in quantum computing 2025";

Console.WriteLine($"Topic: {topic}\n");
Console.WriteLine("Researching... (the agent will search the web and take notes)\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions);

Console.WriteLine("Summary");
Console.WriteLine(new string('-', 50));
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine($"\n({notes.Count} research note(s) were saved during the investigation)");
}

// --- Tool implementations ---

/// <summary>Simulated web search tool that returns realistic search results.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        // Use a free search API (DuckDuckGo Instant Answer API) for real results.
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await s_http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = root.GetProperty("Abstract").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[Main Result] {abstractText}\nSource: {abstractUrl}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var topic in related.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add($"- {text}\n  URL: {firstUrl}");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Thread-safe note-taking store used by the agent.</summary>
class ResearchNotes
{
    private readonly List<(string Title, string Content)> _notes = [];
    private readonly Lock _lock = new();

    public int Count
    {
        get { lock (_lock) return _notes.Count; }
    }

    public void Add(string title, string content)
    {
        lock (_lock)
        {
            _notes.Add((title, content));
        }
    }

    public string GetAll()
    {
        lock (_lock)
        {
            if (_notes.Count == 0)
            {
                return "No notes saved yet.";
            }

            return string.Join("\n\n", _notes.Select((n, i) =>
                $"Note {i + 1}: {n.Title}\n{n.Content}"));
        }
    }
}

